// Obtener el texto del PDF y sus metadatos
const pdfText = $input.item.json.text;
const fileName = $input.item.binary.pdfFile?.fileName || 'uploaded-document.pdf';
const documentTitle = fileName.replace('.pdf', '').replace(/_/g, ' ');

// Limpiar el texto (saltos de pagina, lineas vacias, cabeceras repetidas)
let cleanedText = pdfText
  .replace(/\f/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .replace(/^\d+\s*$/gm, '')
  .trim();

// Calcular metadatos del documento
const wordCount = cleanedText.split(/\s+/).length;
const charCount = cleanedText.length;
const estimatedMinutes = Math.ceil(charCount / 1000);

return {
  json: {
    documentTitle,
    fileName,
    cleanedText,
    wordCount,
    charCount,
    estimatedMinutes,
    uploadDate: new Date().toISOString()
  }
};

const input = $input.item.json;
const cleanedText = input.cleanedText;
const documentTitle = input.documentTitle;

// Limite de bytes por peticion a la API de Google TTS
const MAX_BYTES = 4500;

// Detecta encabezados del tipo "2.1 TITULO EN MAYUSCULAS"
const sectionRegex = /(\d+\.\d+)\s+([A-Z][A-Z\s]{10,})/g;
let sections = [];
let lastIndex = 0;
let match;

while ((match = sectionRegex.exec(cleanedText)) !== null) {
  const sectionNumber = match[1];
  const sectionTitle = match[2].trim();
  const startIndex = match.index;

  if (lastIndex < startIndex) {
    const prevText = cleanedText.substring(lastIndex, startIndex).trim();
    if (prevText.length > 100) {
      sections.push({ text: prevText, number: sections.length + 1, title: 'Introduction' });
    }
  }

  sections.push({ number: sectionNumber, title: sectionTitle, startIndex });
  lastIndex = startIndex;
}

const episodes = [];
for (let i = 0; i < sections.length; i++) {
  const section = sections[i];
  const nextSection = sections[i + 1];
  const endIndex = nextSection ? nextSection.startIndex : cleanedText.length;
  const sectionText = cleanedText.substring(section.startIndex, endIndex).trim();

  // Si la seccion supera el limite, se trocea en varios bloques
  if (Buffer.byteLength(sectionText, 'utf8') > MAX_BYTES) {
    const chunks = splitTextIntoChunks(sectionText, MAX_BYTES);
    chunks.forEach((chunk, idx) => {
      episodes.push({
        episodeNumber: `${section.number}.${idx + 1}`,
        episodeTitle: `${documentTitle} - Section ${section.number}.${idx + 1}: ${section.title}`,
        sectionTitle: section.title,
        textContent: chunk,
        charCount: chunk.length,
        totalEpisodes: null
      });
    });
  } else {
    episodes.push({
      episodeNumber: section.number,
      episodeTitle: `${documentTitle} - Section ${section.number}: ${section.title}`,
      sectionTitle: section.title,
      textContent: sectionText,
      charCount: sectionText.length,
      totalEpisodes: null
    });
  }
}

// Si no se detecto ninguna seccion, se trocea el documento entero por tamano
if (episodes.length === 0) {
  const chunks = splitTextIntoChunks(cleanedText, MAX_BYTES);
  chunks.forEach((chunk, idx) => {
    episodes.push({
      episodeNumber: idx + 1,
      episodeTitle: `${documentTitle} - Part ${idx + 1}`,
      sectionTitle: `Part ${idx + 1}`,
      textContent: chunk,
      charCount: chunk.length,
      totalEpisodes: chunks.length
    });
  });
}

episodes.forEach(ep => ep.totalEpisodes = episodes.length);

// Trocea respetando frases completas, y si no cabe, palabra a palabra
function splitTextIntoChunks(text, maxBytes) {
  const chunks = [];
  let currentChunk = '';
  const sentences = text.split(/(?<=[.!?])\s+/);

  for (const sentence of sentences) {
    const testChunk = currentChunk + (currentChunk ? ' ' : '') + sentence;
    if (Buffer.byteLength(testChunk, 'utf8') > maxBytes) {
      if (currentChunk) {
        chunks.push(currentChunk);
        currentChunk = sentence;
      } else {
        const words = sentence.split(' ');
        for (const word of words) {
          const testWord = currentChunk + (currentChunk ? ' ' : '') + word;
          if (Buffer.byteLength(testWord, 'utf8') > maxBytes) {
            chunks.push(currentChunk);
            currentChunk = word;
          } else {
            currentChunk = testWord;
          }
        }
      }
    } else {
      currentChunk = testChunk;
    }
  }

  if (currentChunk) {
    chunks.push(currentChunk);
  }

  return chunks;
}

return episodes.map(ep => ({ json: ep }));

const now = new Date();
const monthKey = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;

// Contador persistente de consumo mensual guardado en el propio workflow
const monthlyUsage = $getWorkflowStaticData('global');

if (!monthlyUsage[monthKey]) {
  monthlyUsage[monthKey] = { charCount: 0, requestCount: 0 };
}

const currentUsage = monthlyUsage[monthKey].charCount;
const charCount = $input.item.json.charCount;

// Margen de seguridad por debajo del millon gratuito de Google
const MONTHLY_LIMIT = 950000;

if (currentUsage + charCount > MONTHLY_LIMIT) {
  throw new Error(
    `⚠️ LIMITE MENSUAL DE TTS ALCANZADO\n` +
    `Consumido: ${currentUsage.toLocaleString()} caracteres\n` +
    `Esta peticion: ${charCount.toLocaleString()} caracteres\n` +
    `Limite: ${MONTHLY_LIMIT.toLocaleString()} caracteres`
  );
}

return {
  json: {
    ...$input.item.json,
    usageInfo: {
      currentMonthUsage: currentUsage,
      thisRequestChars: charCount,
      remainingChars: MONTHLY_LIMIT - currentUsage - charCount,
      monthKey
    }
  }
};

const audioBase64 = $input.item.json.audioContent;

// Si la llamada al TTS fallo, se descarta este bloque
if (!audioBase64) {
  console.log(`Se omite el elemento ${$itemIndex}: no hay contenido de audio`);
  return null;
}

// Recuperar los metadatos de la seccion correspondiente a este audio
const allSectionItems = $('Detect Sections & Split').all();
const sectionData = allSectionItems[$itemIndex] ? allSectionItems[$itemIndex].json : {};

const episodeTitle = sectionData.episodeTitle || 'Episode';
const episodeNumber = sectionData.episodeNumber || 'N/A';
const sectionTitle = sectionData.sectionTitle || '';
const charCount = sectionData.charCount || 0;

// Construir un nombre de archivo seguro
const date = new Date().toISOString().split('T')[0];
const safeTitle = episodeTitle
  .replace(/[^a-zA-Z0-9\s-]/g, '')
  .replace(/\s+/g, '_')
  .substring(0, 100);
const fileName = `${safeTitle}_${date}.mp3`;

const binaryBuffer = Buffer.from(audioBase64, 'base64');

return {
  json: {
    fileName,
    fileSize: binaryBuffer.length,
    mimeType: 'audio/mpeg',
    episodeTitle,
    episodeNumber,
    sectionTitle,
    charCount,
    audioContent: audioBase64
  },
  binary: {
    audioFile: {
      data: audioBase64,
      mimeType: 'audio/mpeg',
      fileName: fileName,
      fileExtension: 'mp3'
    }
  }
};

const allItems = $input.all();

// Ordenar los fragmentos por numero de episodio antes de unirlos
const sortedItems = allItems.sort((a, b) => {
  const numA = a.json.episodeNumber || 0;
  const numB = b.json.episodeNumber || 0;
  return numA - numB;
});

const mp3Buffers = [];
let totalSize = 0;
let totalChars = 0;
const episodesList = [];

for (const item of sortedItems) {
  const audioData = item.json.audioContent;
  const buffer = Buffer.from(audioData, 'base64');
  mp3Buffers.push(buffer);
  totalSize += buffer.length;
  totalChars += item.json.charCount || 0;

  episodesList.push({
    number: item.json.episodeNumber,
    title: item.json.episodeTitle,
    charCount: item.json.charCount
  });
}

// Concatenar todos los MP3 en uno solo
const combinedBuffer = Buffer.concat(mp3Buffers);
const combinedBase64 = combinedBuffer.toString('base64');

const date = new Date().toISOString().split('T')[0];
const fileName = `Podcast_Completo_${date}.mp3`;

return [{
  json: {
    fileName,
    fileSize: totalSize,
    mimeType: 'audio/mpeg',
    totalEpisodes: sortedItems.length,
    totalCharacters: totalChars,
    episodes: episodesList,
    episodeTitle: `Podcast completo (${sortedItems.length} secciones)`,
    episodeNumber: 'Complete',
    charCount: totalChars
  },
  binary: {
    audioFile: {
      data: combinedBase64,
      mimeType: 'audio/mpeg',
      fileName: fileName,
      fileExtension: 'mp3'
    }
  }
}];

// Datos del MP3 final (vienen del nodo Merge)
const mp3Data = $('Merge').first().json;
const episodes = mp3Data.episodes || [];
const totalEpisodes = mp3Data.totalEpisodes || 1;
const fileName = mp3Data.fileName || 'Podcast.mp3';
const fileSize = mp3Data.fileSize || 0;

// Configuracion centralizada del workflow
const config = $('⚙️ Workflow Config').first().json;
const R2_PUBLIC_URL = config.R2_PUBLIC_URL;
const RSS_FILENAME = config.RSS_FILENAME;
const PODCAST_ARTWORK_URL = config.PODCAST_ARTWORK_URL;

// URL publica del MP3 en R2
const r2Mp3Url = `${R2_PUBLIC_URL}/${fileName}`;
const pubDate = new Date().toUTCString();

// Titulo del documento a partir del nombre de archivo
const docTitle = fileName.replace(/_Completo_\d{4}-\d{2}-\d{2}\.mp3$/, '').replace(/_/g, ' ');

// Duracion estimada (un MP3 a 128 kbps ocupa unos 16 KB por segundo)
const estimatedDurationSeconds = Math.round(fileSize / 16000);
const durationHours = Math.floor(estimatedDurationSeconds / 3600);
const durationMinutes = Math.floor((estimatedDurationSeconds % 3600) / 60);
const durationSeconds = estimatedDurationSeconds % 60;
const durationFormatted = durationHours > 0
  ? `${durationHours}:${String(durationMinutes).padStart(2, '0')}:${String(durationSeconds).padStart(2, '0')}`
  : `${durationMinutes}:${String(durationSeconds).padStart(2, '0')}`;

// Listado de secciones en texto plano
const episodeDescription = episodes.map((ep, idx) =>
  `${idx + 1}. ${ep.title} (${ep.charCount.toLocaleString()} caracteres)`
).join('\n');

// Listado de secciones en HTML
const episodeDescriptionHTML = episodes.map((ep, idx) =>
  `<p><strong>${idx + 1}. ${ep.title}</strong><br/><em>${ep.charCount.toLocaleString()} caracteres</em></p>`
).join('\n');

const currentYear = new Date().getFullYear();

// Feed RSS con metadatos compatibles con iTunes / Apple Podcasts
const rssXml = `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0"
     xmlns:itunes="http://www.itunes.com/dtds/podcast-1.0.dtd"
     xmlns:atom="http://www.w3.org/2005/Atom"
     xmlns:content="http://purl.org/rss/1.0/modules/content/">
  <channel>
    <title>PON_AQUI_EL_NOMBRE_DE_TU_PODCAST</title>
    <description>Convierte cualquier articulo PDF, paper o documento en audio de calidad. Ideal para aprender mientras te desplazas o haces otras cosas.</description>
    <language>es-es</language>
    <link>https://PON_AQUI_TU_WEB.com</link>
    <atom:link href="${R2_PUBLIC_URL}/${RSS_FILENAME}" rel="self" type="application/rss+xml"/>

    <!-- Metadatos de iTunes -->
    <itunes:author>PON_AQUI_TU_NOMBRE</itunes:author>
    <itunes:owner>
      <itunes:name>PON_AQUI_TU_NOMBRE</itunes:name>
      <itunes:email>PON_AQUI_TU_EMAIL</itunes:email>
    </itunes:owner>
    <itunes:image href="${PODCAST_ARTWORK_URL}"/>
    <itunes:category text="Education">
      <itunes:category text="Self-Improvement"/>
    </itunes:category>
    <itunes:category text="Technology"/>
    <itunes:explicit>no</itunes:explicit>
    <itunes:type>episodic</itunes:type>
    <itunes:summary>Tu narrador de IA personal para todo tu material de lectura.</itunes:summary>
    <itunes:subtitle>Articulos PDF convertidos en audio</itunes:subtitle>

    <!-- Metadatos generales -->
    <copyright>© ${currentYear} PON_AQUI_EL_NOMBRE_DE_TU_PODCAST</copyright>
    <generator>n8n.io - Convertir articulos PDF en Podcast</generator>
    <lastBuildDate>${pubDate}</lastBuildDate>

    <!-- Episodio -->
    <item>
      <title>${docTitle} - Completo (${totalEpisodes} secciones)</title>
      <description><![CDATA[
        📚 Edicion completa en audio de ${docTitle}

        🎯 Contenido:
        ${episodeDescription}

        ⏱️ Duracion: ${durationFormatted}
        📄 Secciones: ${totalEpisodes}
        🗓️ Publicado: ${new Date().toLocaleDateString('es-ES', { month: 'long', day: 'numeric', year: 'numeric' })}
      ]]></description>
      <enclosure url="${r2Mp3Url}" length="${fileSize}" type="audio/mpeg"/>
      <guid isPermaLink="false">${fileName}</guid>
      <pubDate>${pubDate}</pubDate>

      <itunes:title>${docTitle} - Edicion completa</itunes:title>
      <itunes:author>PON_AQUI_TU_NOMBRE</itunes:author>
      <itunes:duration>${durationFormatted}</itunes:duration>
      <itunes:summary><![CDATA[Version completa en audio con ${totalEpisodes} secciones. ${episodeDescription.substring(0, 150)}...]]></itunes:summary>
      <itunes:subtitle>${totalEpisodes} secciones • ${durationFormatted}</itunes:subtitle>
      <itunes:image href="${PODCAST_ARTWORK_URL}"/>
      <itunes:episodeType>full</itunes:episodeType>
      <itunes:explicit>no</itunes:explicit>

      <content:encoded><![CDATA[
        <h2>🎧 ${docTitle} - Edicion completa en audio</h2>
        <p><strong>Duracion:</strong> ${durationFormatted} | <strong>Secciones:</strong> ${totalEpisodes} | <strong>Tamano:</strong> ${Math.round(fileSize / 1024 / 1024 * 100) / 100} MB</p>
        <hr/>
        <h3>📑 Secciones incluidas:</h3>
        ${episodeDescriptionHTML}
        <hr/>
        <p><em>Generado automaticamente con el workflow Convertir articulos PDF en Podcast</em></p>
      ]]></content:encoded>
    </item>

  </channel>
</rss>`;

// Convertir el XML a base64 para poder subirlo como archivo
const rssBase64 = Buffer.from(rssXml, 'utf-8').toString('base64');

return {
  json: {
    ...mp3Data,
    r2Mp3Url: r2Mp3Url,
    rssGenerated: true,
    rssFileName: RSS_FILENAME,
    estimatedDuration: durationFormatted,
    podcastArtwork: PODCAST_ARTWORK_URL
  },
  binary: {
    rssFile: {
      data: rssBase64,
      mimeType: 'application/rss+xml',
      fileName: RSS_FILENAME,
      fileExtension: 'xml'
    }
  }
};

// Datos del MP3 final (vienen del nodo Merge)
const data = $('Merge').first().json;
const totalChars = data.totalCharacters || data.charCount || 0;
const totalEpisodes = data.totalEpisodes || 1;

const now = new Date();
const monthKey = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;

// Contador persistente guardado en el propio workflow
const monthlyUsage = $getWorkflowStaticData('global');

if (!monthlyUsage[monthKey]) {
  monthlyUsage[monthKey] = {
    charCount: 0,
    requestCount: 0,
    lastUpdated: new Date().toISOString()
  };
}

// Sumar el consumo de esta ejecucion
monthlyUsage[monthKey].charCount += totalChars;
monthlyUsage[monthKey].requestCount += totalEpisodes;
monthlyUsage[monthKey].lastUpdated = new Date().toISOString();

return {
  json: {
    ...data,
    updatedUsage: {
      monthKey,
      totalChars: monthlyUsage[monthKey].charCount,
      totalRequests: monthlyUsage[monthKey].requestCount,
      lastUpdated: monthlyUsage[monthKey].lastUpdated,
      percentUsed: Math.round((monthlyUsage[monthKey].charCount / 950000) * 100)
    }
  }
};

// Datos del MP3 final (vienen del nodo Merge)
const data = $('Merge').first().json;
const episodes = data.episodes || [];
const totalChars = data.totalCharacters || data.charCount || 0;
const totalEpisodes = data.totalEpisodes || episodes.length;
const mp3FileSize = data.fileSize || 0;
const mp3FileName = data.fileName || 'Podcast.mp3';
const mp3FileNameWithoutExt = mp3FileName.replace(/\.mp3$/i, '').replace(/_Completo_\d{4}-\d{2}-\d{2}$/, '');

// URL publica del feed RSS
const config = $('⚙️ Workflow Config').first().json;
const R2_PUBLIC_URL = config.R2_PUBLIC_URL;
const RSS_FILENAME = config.RSS_FILENAME;
const rssFeedUrl = `${R2_PUBLIC_URL}/${RSS_FILENAME}`;

// Datos de consumo mensual
const usageData = data.updatedUsage || {
  totalChars: totalChars,
  totalRequests: totalEpisodes,
  percentUsed: Math.round((totalChars / 950000) * 100)
};

// Listado de secciones en HTML
const episodeListHTML = episodes.map((ep, idx) =>
  `<li><strong>${ep.title}</strong><br>Seccion ${ep.number} | ${ep.charCount.toLocaleString()} caracteres</li>`
).join('\n');

// Cuerpo del email
const emailHTML = `
<h2>🎧 Nuevo episodio de podcast disponible</h2>

<p><strong>Total de secciones:</strong> ${totalEpisodes} (unidas en un unico archivo)</p>
<p><strong>Total de caracteres:</strong> ${totalChars.toLocaleString()}</p>
<p><strong>Tamano del archivo:</strong> ${Math.round(mp3FileSize / 1024 / 1024 * 100) / 100} MB</p>
<p><strong>Nombre del archivo:</strong> ${mp3FileNameWithoutExt}</p>

<hr>

<h3>📋 Secciones creadas:</h3>
<ul>
${episodeListHTML}
</ul>

<hr>

<h3>📡 Suscribirse al podcast</h3>
<p>Copia esta URL del feed RSS y pegala en tu app de podcast:</p>
<p style="background-color: #f0f0f0; padding: 10px; font-family: monospace; word-break: break-all; font-size: 12px;">${rssFeedUrl}</p>
<p><em>Compatible con Apple Podcasts, Spotify, Pocket Casts, Overcast, Castro y la mayoria de apps.</em></p>

<hr>

<h3>📊 Consumo mensual</h3>
<p><strong>Usado:</strong> ${usageData.totalChars.toLocaleString()} / 950.000 caracteres (${usageData.percentUsed}%)</p>
<p><strong>Secciones generadas este mes:</strong> ${usageData.totalRequests}</p>

<hr>

<p style="color: #666;">✅ Las ${totalEpisodes} secciones estan unidas en un unico MP3 alojado en Cloudflare R2.</p>
<p style="color: #666;">✅ Feed RSS generado y listo para suscribirse.</p>
`;

return {
  json: {
    totalEpisodes: totalEpisodes,
    totalCharacters: totalChars,
    rssFeedUrl: rssFeedUrl,
    emailSubject: `Nuevo podcast: ${totalEpisodes} secciones de ${mp3FileNameWithoutExt}`,
    emailHTML: emailHTML,
    usageData: usageData
  }
};
